program='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            minr = min(y for y,x in cells); maxr = max(y for y,x in cells)
            minc = min(x for y,x in cells); maxc = max(x for y,x in cells)
            shape = {(y-minr,x-minc) for y,x in cells}
            # A shape enclosing background is sent to the top; open shapes to the bottom.
            bh, bw = maxr-minr+1, maxc-minc+1
            outside = set()
            flood = deque()
            for yy in range(bh):
                for xx in range(bw):
                    if (yy,xx) not in shape and (yy in (0,bh-1) or xx in (0,bw-1)):
                        outside.add((yy,xx)); flood.append((yy,xx))
            while flood:
                yy,xx = flood.popleft()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=yy+dy,xx+dx
                    if 0<=ny<bh and 0<=nx<bw and (ny,nx) not in shape and (ny,nx) not in outside:
                        outside.add((ny,nx)); flood.append((ny,nx))
            has_hole = any((yy,xx) not in shape and (yy,xx) not in outside for yy in range(bh) for xx in range(bw))
            objects.append({'color':color,'cells':cells,'shape':shape,'r':minr,'c':minc,'height':bh,'up':has_hole})
    out = [[0]*w for _ in range(h)]
    placed = []
    # Hollow objects are packed from the top down; open objects from the bottom up.
    for up in (True, False):
        group = [o for o in objects if o['up'] == up]
        group.sort(key=lambda o: o['r'], reverse=not up)
        for o in group:
            bh=o['height']; c=o['c']
            starts = range(0,h-bh+1) if up else range(h-bh,-1,-1)
            chosen = None
            for nr in starts:
                candidate={(nr+yy,c+xx) for yy,xx in o['shape']}
                if not any(candidate & p for p in placed):
                    chosen=nr; placed.append(candidate); break
            if chosen is None:
                chosen=o['r']; placed.append({(y,x) for y,x in o['cells']})
            for yy,xx in o['shape']:
                out[chosen+yy][c+xx]=o['color']
    return out
'''
